export function MapEmbed({
  title = "{{title}}",
  theme = "{{theme}}",
  zoom = {{zoom}},
  rounded = {{rounded}},
}) {
  const dark = theme === "dark";
  return (
    <div
      role="img"
      aria-label={`Map preview: ${title}, zoom level ${zoom}`}
      style={{
        position: "relative", maxWidth: 360, aspectRatio: "4 / 3", overflow: "hidden",
        border: "1px solid #24143022", display: "flex", alignItems: "flex-end",
        borderRadius: rounded ? 14 : 0,
        background: dark ? "#241430" : "#FAF7F2",
        backgroundImage: `repeating-linear-gradient(0deg, ${dark ? "#ffffff14" : "#24143014"} 0 1px, transparent 1px 24px), repeating-linear-gradient(90deg, ${dark ? "#ffffff14" : "#24143014"} 0 1px, transparent 1px 24px)`,
      }}
    >
      {/* Replace with a real embed in production, e.g.
      <iframe title={title} src="https://your-map-provider.example/embed?q=..." loading="lazy" style={{ border: 0 }} /> */}
      <svg style={{ position: "absolute", top: "42%", left: "48%", transform: "translate(-50%, -100%)" }} viewBox="0 0 24 24" width={26} height={26} aria-hidden="true">
        <path d="M12 2c-4 0-7 3-7 7 0 5 7 13 7 13s7-8 7-13c0-4-3-7-7-7z" fill="#E8A020" />
        <circle cx="12" cy="9" r="2.6" fill="#FAF7F2" />
      </svg>
      <p style={{ margin: 0, padding: "6px 10px", font: "600 12px/1.4 system-ui, sans-serif", background: "#241430cc", color: "#FAF7F2", width: "100%" }}>
        {title} · zoom {zoom}
      </p>
    </div>
  );
}
